begin;
select plan(31);
insert into auth.users(id,email) values
 ('11111111-1111-4111-8111-111111111111','preview-owner@example.test'),
 ('22222222-2222-4222-8222-222222222222','preview-other@example.test');
select public.get_or_create_account_profile('11111111-1111-4111-8111-111111111111','preview-owner@example.test',true);
select public.get_or_create_account_profile('22222222-2222-4222-8222-222222222222','preview-other@example.test',true);
create temporary table item as select * from public.submit_fetch_items('11111111-1111-4111-8111-111111111111',array['https://example.test/fragment']);
create temporary table job as select * from public.claim_processing_job('11111111-1111-4111-8111-111111111111');
select public.set_processing_stage(user_id,id,lease_token,'fetching','processing') from job;
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'legacy submission has no preview consent');
select throws_ok($$select public.allow_partial_previews('11111111-1111-4111-8111-111111111111',array[(select id from item)],false)$$,'P0001','preview_consent_required','consent cannot be false');
select is((select count(*)::int from public.allow_partial_previews('22222222-2222-4222-8222-222222222222',array[(select id from item)],true)),0,'foreign owner cannot enable preview');
select public.allow_partial_previews(user_id,array[item_id],true) from job;
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview('22222222-2222-4222-8222-222222222222',j.id,j.lease_token,0.14848)),0,'foreign owner cannot reserve');
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,gen_random_uuid(),0.14848)),0,'stale lease cannot reserve');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',0);
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'zero budget prevents a paid preview');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',10);
update public.items set expires_at=now()-interval '1 second' where id=(select id from item);
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'expired item cannot reserve');
update public.items set expires_at=now()+interval '1 day' where id=(select id from item);
update public.account_profiles set status='rejected' where user_id='11111111-1111-4111-8111-111111111111';
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'rejected account cannot reserve');
update public.account_profiles set status='approved' where user_id='11111111-1111-4111-8111-111111111111';
create temporary table call as select r.* from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848) r;
select is((select count(*)::int from call),1,'one preview admitted');
select is((select count(*)::int from job j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'same job cannot repeat paid preview');
select is((select count(*)::int from job j cross join call r cross join lateral public.record_partial_preview(j.user_id,j.id,gen_random_uuid(),r.id,'Wrong stale overview.','gen-preview')),0,'stale lease cannot save preview');
select is((select count(*)::int from job j cross join call r cross join lateral public.record_partial_preview('22222222-2222-4222-8222-222222222222',j.id,j.lease_token,r.id,'Foreign overview.','foreign-gen')),0,'foreign owner cannot save preview');
select is((select count(*)::int from job j cross join call r cross join lateral public.record_partial_preview(j.user_id,j.id,j.lease_token,r.id,E'Bad\nmultiline','gen-preview')),0,'invalid model preview cannot be saved');
select is((select generation_id from public.usage_reservations where id=(select id from call)),'gen-preview','late generation preserved for reconciliation');
select public.record_partial_preview(j.user_id,j.id,j.lease_token,r.id,'The fragment describes organizing email into a knowledge library.','gen-preview') from job j cross join call r;
select is((select count(*)::int from public.source_contents where item_id=(select id from item)),0,'partial text never saved as complete source');
select is((select count(*)::int from public.assessments where item_id=(select id from item)),0,'preview never creates an assessment');
select public.set_processing_stage(user_id,id,lease_token,'partial_content','awaiting_manual_content') from job;
select is((select status::text from public.items where id=(select id from item)),'awaiting_manual_content','needs action status retained');
select is((select partial_overview from public.list_processing_items('11111111-1111-4111-8111-111111111111')),'The fragment describes organizing email into a knowledge library.','owned inbox exposes overview');
select is((select count(*)::int from public.list_processing_items('22222222-2222-4222-8222-222222222222')),0,'foreign inbox cannot expose preview');
select is((select count(*)::int from public.resume_processing_item('11111111-1111-4111-8111-111111111111',(select id from item))),0,'unknown charge prevents retry');
select is((select preview_charge_pending from public.list_processing_items('11111111-1111-4111-8111-111111111111')),true,'unknown charge exposed for disabled retry');
select public.settle_analysis(j.user_id,r.id,0.001) from job j cross join call r;
select is((select preview_charge_pending from public.list_processing_items('11111111-1111-4111-8111-111111111111')),false,'known charge clears retry warning');
select public.resume_processing_item('11111111-1111-4111-8111-111111111111',(select id from item));
create temporary table reclaimed as select * from public.claim_processing_job('11111111-1111-4111-8111-111111111111');
select is((select count(*)::int from reclaimed j cross join lateral public.reserve_partial_preview(j.user_id,j.id,j.lease_token,0.14848)),0,'explicit fetch retry does not resend preview');
set local role authenticated;
select throws_ok($$select public.reserve_partial_preview('11111111-1111-4111-8111-111111111111',gen_random_uuid(),gen_random_uuid(),0.1)$$,'42501',null,'browser cannot invoke budget RPC');
reset role;
select public.delete_items('11111111-1111-4111-8111-111111111111',array[(select id from item)],true);
select is((select count(*)::int from public.items where id=(select id from item)),0,'deletion removes preview metadata');
select public.record_partial_preview(j.user_id,j.id,j.lease_token,r.id,'Never restore deleted content.','gen-preview') from job j cross join call r;
select is((select count(*)::int from public.items where id=(select id from item)),0,'late preview cannot resurrect item');
select is((select job_id from public.usage_reservations where id=(select id from call)),null::uuid,'detached charge remains after deletion');
select is((select generation_id from public.usage_reservations where id=(select id from call)),'gen-preview','detached billing retains generation');
create temporary table atomic_fetch as select * from public.submit_fetch_items('11111111-1111-4111-8111-111111111111',array['https://example.test/atomic-fetch'],true);
select is((select partial_preview_allowed from public.jobs where item_id=(select id from atomic_fetch)),true,'fetch submission atomically saves preview consent');
create temporary table atomic_search as select * from public.submit_search_items('11111111-1111-4111-8111-111111111111',array['https://example.test/atomic-search'],true);
select is((select partial_preview_allowed from public.jobs where item_id=(select id from atomic_search)),true,'search submission atomically saves preview consent');
create temporary table legacy_retry as select * from public.submit_fetch_items('11111111-1111-4111-8111-111111111111',array['https://example.test/old-retry']);
update public.items set status='awaiting_manual_content',processing_stage='partial_content' where id=(select id from legacy_retry);
update public.jobs set status='awaiting_manual_content',processing_stage='partial_content' where item_id=(select id from legacy_retry);
select public.resume_processing_item('11111111-1111-4111-8111-111111111111',(select id from legacy_retry),true);
select is((select partial_preview_allowed from public.jobs where item_id=(select id from legacy_retry)),true,'retry atomically saves newly disclosed consent');
select * from finish();
rollback;
